const myanmarDigits: Record<string, string> = {"၀":"0","၁":"1","၂":"2","၃":"3","၄":"4","၅":"5","၆":"6","၇":"7","၈":"8","၉":"9"};

function asciiDigits(value: unknown) {
  return String(value ?? "").normalize("NFC").replace(/[၀-၉]/g, (d) => myanmarDigits[d]);
}

function locationKey(value: unknown) {
  return asciiDigits(value)
    .toLowerCase()
    .replace(/\b(?:township|town|city|region|state|union territory)\b/g, " ")
    .replace(/(?:မြို့နယ်|မြို့|တိုင်းဒေသကြီး|ပြည်နယ်|ပြည်ထောင်စုနယ်မြေ)/g, " ")
    .replace(/[^a-z0-9\u1000-\u109f]+/g, "")
    .trim();
}

function decodeBase64(value: string) {
  if (typeof globalThis.atob === "function") {
    const text = globalThis.atob(value);
    const out = new Uint8Array(text.length);
    for (let i = 0; i < text.length; i += 1) out[i] = text.charCodeAt(i);
    return out;
  }
  const BufferCtor = (globalThis as any).Buffer;
  if (BufferCtor) return new Uint8Array(BufferCtor.from(value, "base64"));
  throw new Error("Base64 decoding is unavailable.");
}

function readVarint(bytes: Uint8Array, state: { offset: number }) {
  let value = 0;
  let multiplier = 1;
  while (state.offset < bytes.length) {
    const byte = bytes[state.offset++];
    value += (byte & 0x7f) * multiplier;
    if ((byte & 0x80) === 0) break;
    multiplier *= 128;
  }
  return (value & 1) ? -((value + 1) / 2) : (value / 2);
}

const postalCompositeKeys = POSTAL_CODE_ROWS.map(([townshipIndex, _quarter, postalCode, quarterMm]) => {
  const townshipMm = POSTAL_CODE_TOWNSHIPS[townshipIndex][1];
  return `${String(postalCode).padStart(7, "0")}\u001f${String(townshipMm).trim()}\u001f${String(quarterMm).trim()}`;
}).sort((a, b) => a.localeCompare(b, "en"));

let postalCoordinates: Array<readonly [number, number]> | null = null;
let postalIndex: Map<string, number> | null = null;

function ensurePostalCoordinates() {
  if (postalCoordinates && postalIndex) return;
  const bytes = decodeBase64(POSTAL_COORDINATE_PACKED);
  const state = { offset: 0 };
  let lat = 0;
  let lng = 0;
  const decoded: Array<readonly [number, number]> = [];
  for (let i = 0; i < postalCompositeKeys.length; i += 1) {
    lat += readVarint(bytes, state);
    lng += readVarint(bytes, state);
    decoded.push([lat / 1_000_000, lng / 1_000_000] as const);
  }
  if (decoded.length !== 17331 || state.offset !== bytes.length) {
    throw new Error("V136 postal coordinate master is out of sync with postalCodeData.ts");
  }
  postalCoordinates = decoded;
  postalIndex = new Map(postalCompositeKeys.map((key, index) => [key, index]));
}

export function postalWardDefaultCoordinate(postal: {
  postalCode?: unknown;
  townshipMm?: unknown;
  quarterMm?: unknown;
  township?: unknown;
  quarter?: unknown;
}) {
  const code = asciiDigits(postal.postalCode).trim().padStart(7, "0");
  if (!/^\d{7}$/.test(code) || !postal.townshipMm || !postal.quarterMm) return null;
  ensurePostalCoordinates();
  const composite = `${code}\u001f${String(postal.townshipMm).trim()}\u001f${String(postal.quarterMm).trim()}`;
  const index = postalIndex!.get(composite);
  if (index === undefined) return null;
  const [latitude, longitude] = postalCoordinates![index];
  return {
    latitude,
    longitude,
    label: [postal.quarter || postal.quarterMm, postal.township || postal.townshipMm, code].filter(Boolean).join(", "),
    source: "POSTAL_WARD_DEFAULT_V136" as const,
    level: "POSTAL_DEFAULT" as const,
  };
}

type TownshipDefaultRow = readonly [string, string, string, string, number, number];
const townshipDefaults = TOWNSHIP_DEFAULT_ROWS as readonly TownshipDefaultRow[];

function regionMatches(rowRegion: string, region: unknown, address: unknown) {
  const rowKey = locationKey(rowRegion);
  const regionKey = locationKey(region);
  const addressKey = locationKey(address);
  return Boolean(rowKey && (
    (regionKey && (rowKey.includes(regionKey) || regionKey.includes(rowKey)))
    || (addressKey && addressKey.includes(rowKey))
  ));
}

function postalCentroidForTownship(township: unknown) {
  const wanted = locationKey(township);
  if (!wanted) return null;
  ensurePostalCoordinates();
  let lat = 0;
  let lng = 0;
  let count = 0;
  for (const [townshipIndex, _quarter, postalCode, quarterMm] of POSTAL_CODE_ROWS) {
    const town = POSTAL_CODE_TOWNSHIPS[townshipIndex];
    if (![locationKey(town[0]), locationKey(town[1])].includes(wanted)) continue;
    const composite = `${String(postalCode).padStart(7, "0")}\u001f${String(town[1]).trim()}\u001f${String(quarterMm).trim()}`;
    const index = postalIndex!.get(composite);
    if (index === undefined) continue;
    lat += postalCoordinates![index][0];
    lng += postalCoordinates![index][1];
    count += 1;
  }
  return count ? { latitude: lat / count, longitude: lng / count } : null;
}

export function townshipDefaultCoordinate(township: unknown, region: unknown = "", address: unknown = "") {
  const wanted = locationKey(township);
  if (!wanted) return null;
  let candidates = townshipDefaults.filter((row) => [locationKey(row[2]), locationKey(row[3])].includes(wanted));
  if (candidates.length > 1) {
    const narrowed = candidates.filter((row) => regionMatches(row[0], region, address));
    if (narrowed.length) candidates = narrowed;
  }
  if (candidates.length === 1) {
    const row = candidates[0];
    return {
      latitude: row[4] / 1_000_000,
      longitude: row[5] / 1_000_000,
      label: `${row[2]} / ${row[3]} township default`,
      source: "TOWNSHIP_DEFAULT_V136" as const,
      level: "TOWNSHIP_DEFAULT" as const,
    };
  }
  const centroid = postalCentroidForTownship(township);
  if (!centroid) return null;
  return {
    ...centroid,
    label: `${String(township || "").trim()} generic township default`,
    source: "TOWNSHIP_DEFAULT_V136" as const,
    level: "TOWNSHIP_DEFAULT" as const,
  };
}

export const DEFAULT_LOCATION_MASTER_COUNTS = { postalAreas: 17331, townships: 356 } as const;
